    "observation": "混合后温度迅速上升，约 1–2 分钟达到最高点，随后缓慢下降；对照组的温升明显更小。",
    "conclusion": "强酸与强碱的稀溶液中和热约为 −57.3 kJ/mol。测定值通常偏小，主要因为量热计向环境散热、盖口蒸发和搅拌带入热量。",
